# -*- coding: utf-8 -*-
"""Bổ sung các NHÀ GA nổi tiếng, biểu tượng của các tỉnh/thành (đơn vị MỚI sau sáp nhập 1/7/2025).
Toạ độ THẬT (OSM/Wikidata). Chèn an toàn theo từng file: bỏ qua slug đã có. maps để trống (retrofit sinh).
"""
import json, os

def rec(file, rn, fd, slug, name_vi, name_en, name_ru, cats, lat, lon, addr, rating, review,
        ps_vi, ps_en, ps_ru, pl_vi, pl_en, pl_ru, hi_vi, hi_en, hi_ru, practical, tags, sources,
        photo=None, photo_credit=None):
    region = file
    return (file, {
        "id": f"{region}-{slug}", "slug": slug, "region": region, "country": "vietnam",
        "region_name_vi": rn, "federal_district": fd,
        "name_vi": name_vi, "name_ru": name_ru, "name_en": name_en,
        "categories": cats, "coordinates": {"lat": lat, "lon": lon},
        "address_vi": addr, "rating": rating, "review_summary_vi": review,
        "presentation_short_vi": ps_vi, "presentation_short_en": ps_en, "presentation_short_ru": ps_ru,
        "presentation_long_vi": pl_vi, "presentation_long_en": pl_en, "presentation_long_ru": pl_ru,
        "highlights_vi": hi_vi, "highlights_en": hi_en, "highlights_ru": hi_ru,
        "practical": practical, "photo": photo, "photo_credit": photo_credit,
        "maps": {}, "official_site": None, "sources": sources, "tags": tags,
        "status": "enriched", "last_updated": "2026-07-28",
    })

