from collections import defaultdict
bygroup = defaultdict(list)
for f, r in ITEMS:
    bygroup[f].append(r)

total_added = 0
for f, recs in bygroup.items():
    path = f"data/regions/{f}.json"
    d = json.load(open(path, encoding="utf-8")) if os.path.exists(path) else []
    have = {p["slug"] for p in d}
    add = [r for r in recs if r["slug"] not in have]
    d += add
    json.dump(d, open(path, "w", encoding="utf-8"), ensure_ascii=False, indent=2)
    total_added += len(add)
    print(f"{f}: +{len(add)} ({', '.join(r['slug'] for r in add)}) -> tong {len(d)}")
print("TONG DA THEM:", total_added)
